import test from 'node:test';import assert from 'node:assert/strict';
import {boxObstacle,overlaps,clearSegment,detour,avoidStep,freePoint} from './ranch-navigation.mjs';
test('rotated footprints and swept motion block tunnelling',()=>{const wall=boxObstacle(0,0,4,1,Math.PI/2);assert.ok(overlaps({x:0,z:1},.3,wall));assert.equal(overlaps({x:2,z:0},.3,wall),false);assert.equal(clearSegment({x:-5,z:0},{x:5,z:0},.3,[wall]),false);});
test('detour walks around a building with clearance on every segment',()=>{const obstacles=[boxObstacle(0,0,3,3)],a={x:-5,z:0},b={x:5,z:0};const route=detour(a,b,.3,obstacles);assert.ok(route);let p=a;for(const q of route){assert.ok(clearSegment(p,q,.3,obstacles));p=q;}assert.deepEqual(p,b);});
test('sealed space reports no route rather than walking through a wall',()=>{assert.equal(detour({x:-2,z:0},{x:2,z:0},.3,[boxObstacle(0,0,1,10)],p=>Math.abs(p.x)<4&&Math.abs(p.z)<3),null);});
test('opposing walkers pass without overlapping',()=>{let a={x:-2,z:0},b={x:2,z:0};for(let i=0;i<300;i++){a=avoidStep(a,{x:3,z:0},.08,.3,[],[{...b,radius:.3}]);b=avoidStep(b,{x:-3,z:0},.08,.3,[],[{...a,radius:.3}]);assert.ok(Math.hypot(a.x-b.x,a.z-b.z)>=.6-1e-8);}assert.ok(a.x>2);assert.ok(b.x<-2);});
test('pen boundary and feeder stay solid while animal approaches',()=>{let p={x:0,z:0};const bounds=(q,r)=>Math.abs(q.x)<3-r&&Math.abs(q.z)<3-r,obstacles=[boxObstacle(0,2,1.8,.8)];for(let i=0;i<200;i++){p=avoidStep(p,{x:0,z:5},.1,.65,obstacles,[],bounds);assert.ok(bounds(p,.65));assert.ok(!overlaps(p,.65,obstacles[0]));}assert.ok(freePoint({x:0,z:2},.65,obstacles,bounds));});
test('a departing worker can pass an arriving worker beside a pickup wall',()=>{const obstacles=[boxObstacle(0,0,5,3)];let a={x:0,z:2.15},b={x:.7,z:4};const home={x:-3,z:5},pickup={x:.8,z:2.15};for(let i=0;i<500;i++){a=avoidStep(a,home,.06,.3,obstacles,[{...b,radius:.3}]);b=avoidStep(b,pickup,.06,.3,obstacles,[{...a,radius:.3}]);assert.ok(Math.hypot(a.x-b.x,a.z-b.z)>.599);}assert.ok(Math.hypot(a.x-home.x,a.z-home.z)<.1);assert.ok(Math.hypot(b.x-pickup.x,b.z-pickup.z)<.1);});
